// The document head from head.gen.json (generated by lean/Fw/Site/Head.lean): rendering for the build, and the parse
// used by the test that compares a built page with the snapshot head.
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const unesc = (s) => s.replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
const byKey = (x, y) => (x[0] < y[0] ? -1 : x[0] > y[0] ? 1 : 0);

export const renderEntry = (e) => {
  const attrs = e.attrs.map(([k, v]) => ` ${k}="${esc(v)}"`).join('');
  return e.tag === 'title' ? `<title>${esc(e.text)}</title>` : `<${e.tag}${attrs}>`;
};
export const renderHead = (gen) => gen.entries.map(renderEntry).join('');
const SR_ONLY =
  'position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0 0 0 0);clip-path:inset(50%);white-space:nowrap;border:0';
/** The language links: the last element of the body, outside the app mount point, as in the original. */
export const renderLocaleLinks = (gen) =>
  `<nav class="site-locale-links" aria-label="Language" style="${SR_ONLY}">` +
  gen.locales.map((l) => `<a href="${esc(l.href)}" hreflang="${esc(l.code)}" lang="${esc(l.code)}">${esc(l.label)}</a>`).join('') +
  '</nav>';
export const htmlAttrs = (gen) => Object.entries(gen.html).map(([k, v]) => `${k}="${esc(v)}"`).join(' ');

/** Every meta, link and title element of the document's `<head>`, as {tag, attrs (sorted pairs), text}. */
export const parseHead = (html) => {
  const head = /<head[^>]*>([\s\S]*?)<\/head>/.exec(html)?.[1] ?? '';
  const out = [];
  for (const m of head.matchAll(/<(meta|link)\b([^>]*?)\/?>|<title>([\s\S]*?)<\/title>/g)) {
    if (m[3] !== undefined) {
      out.push({ tag: 'title', attrs: [], text: unesc(m[3]) });
      continue;
    }
    const attrs = [...m[2].matchAll(/([\w:-]+)="([^"]*)"/g)].map((a) => [a[1], unesc(a[2])]);
    out.push({ tag: m[1], attrs: attrs.sort(byKey), text: '' });
  }
  return out;
};
export const normEntry = (e) => ({ tag: e.tag, attrs: [...e.attrs].sort(byKey), text: e.text });

export const parseHtmlAttrs = (html) => {
  const tag = /<html\b([^>]*)>/.exec(html)?.[1] ?? '';
  return Object.fromEntries([...tag.matchAll(/([\w-]+)="([^"]*)"/g)].map((a) => [a[1], unesc(a[2])]));
};
